 215 |             bool shouldPlugin = ordrStat.U_ReceivePayStatus == 1 ||
 216 |                                (paymentRate >= 0.98m && Math.Abs(balanceRMB) < 100m);
 217 | 
 218 |             if (!shouldPlugin) return;
 219 | 
 220 |             await ProcessPluginAsync(orderId, ordr, ordrStat, docTotalRMB, balanceRMB, paymentRate);
 221 |         }
